window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2bcf62b28e396ca6"]={"versions": [{"id": "FIG-2bcf62b28e396ca6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der AUTOSAR-XML-Persistenzregeln (AUTOSAR XML Persistence Rules). Es definiert die standardisierte Transformationslogik für UML-Properties mit der Assoziationseigenschaft <code>aggregation = none</code> (Referenzbeziehung statt Aggregation oder Komposition) in die entsprechende XML-Schema- und Instanz-Struktur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>:Property</code>: Eingangs-Objektknoten bzw. metamodelläre Entität einer Assoziation ohne Aggregation.</li>\n<li>Verzweigungsknoten (Decision Node) <code>propertyWrapper?</code>: Verzweigungspunkt zur Fallunterscheidung über das Vorhandensein eines Wrapper-Elements.</li>\n<li><code>[APRXML0017] Create reference property (1)</code>: Transformationsaktion zur Erzeugung einer Referenz-Property mit Wrapper-Element (<code>[propertyWrapperElement]</code>).</li>\n<li><code>[APRXML0018] Create reference property (0)</code>: Transformationsaktion zur Erzeugung einer Referenz-Property ohne Wrapper-Element (<code>[NOT propertyWrapperElement]</code>).</li>\n<li>Zusammenführungsknoten (Merge Node): Rauten-Knoten zur Vereinigung beider Ausführungspfade.</li>\n<li><code>ActivityFinal</code>: Aktivitätsendknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend von der zu transformierenden Entität <code>:Property</code> erreicht der Kontrollfluss die Verzweigung <code>propertyWrapper?</code>.</li>\n<li>Bei Vorliegen der Guard-Bedingung <code>[propertyWrapperElement]</code> wird der Pfad zu <code>[APRXML0017] Create reference property (1)</code> aktiviert und die Referenz inklusive umschließendem XML-Element erzeugt.</li>\n<li>Bei Vorliegen der negierten Bedingung <code>[NOT propertyWrapperElement]</code> wird der Pfad zu <code>[APRXML0018] Create reference property (0)</code> beschritten, wodurch die Referenz direkt ohne Wrapper erzeugt wird.</li>\n<li>Beide Pfade vereinigen sich im nachfolgenden Merge-Knoten und führen direkt zum Aktivitätsendknoten <code>ActivityFinal</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verankert normativ die Verzweigung zwischen den AUTOSAR-Produktionsregeln APRXML0017 und APRXML0018. Entwickler von Modellierungs-, Schema- und Serialisierungswerkzeugen müssen sicherstellen, dass bei UML-Properties mit <code>aggregation = none</code> die Auswertung von Metamodell-Tags und Stereotypen bezüglich des Wrapper-Elements exakt dieser Fallunterscheidung folgt, um standardkonforme ARXML-Strukturen zu gewährleisten.</p>"}, {"id": "FIG-05b7b8d6f986c53b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der AUTOSAR-XML-Persistenzregeln (AUTOSAR XML Persistence Rules). Es definiert die standardisierte Transformationslogik für UML-Properties mit der Assoziationseigenschaft <code>aggregation = none</code> (Referenzbeziehung statt Aggregation oder Komposition) in die entsprechende XML-Schema- und Instanz-Struktur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>:Property</code>: Eingangs-Objektknoten bzw. metamodelläre Entität einer Assoziation ohne Aggregation.</li>\n<li>Verzweigungsknoten (Decision Node) <code>propertyWrapper?</code>: Verzweigungspunkt zur Fallunterscheidung über das Vorhandensein eines Wrapper-Elements.</li>\n<li><code>[APRXML0017] Create reference property (1)</code>: Transformationsaktion zur Erzeugung einer Referenz-Property mit Wrapper-Element (<code>[propertyWrapperElement]</code>).</li>\n<li><code>[APRXML0018] Create reference property (0)</code>: Transformationsaktion zur Erzeugung einer Referenz-Property ohne Wrapper-Element (<code>[NOT propertyWrapperElement]</code>).</li>\n<li>Zusammenführungsknoten (Merge Node): Rauten-Knoten zur Vereinigung beider Ausführungspfade.</li>\n<li><code>ActivityFinal</code>: Aktivitätsendknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend von der zu transformierenden Entität <code>:Property</code> erreicht der Kontrollfluss die Verzweigung <code>propertyWrapper?</code>.</li>\n<li>Bei Vorliegen der Guard-Bedingung <code>[propertyWrapperElement]</code> wird der Pfad zu <code>[APRXML0017] Create reference property (1)</code> aktiviert und die Referenz inklusive umschließendem XML-Element erzeugt.</li>\n<li>Bei Vorliegen der negierten Bedingung <code>[NOT propertyWrapperElement]</code> wird der Pfad zu <code>[APRXML0018] Create reference property (0)</code> beschritten, wodurch die Referenz direkt ohne Wrapper erzeugt wird.</li>\n<li>Beide Pfade vereinigen sich im nachfolgenden Merge-Knoten und führen direkt zum Aktivitätsendknoten <code>ActivityFinal</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verankert normativ die Verzweigung zwischen den AUTOSAR-Produktionsregeln APRXML0017 und APRXML0018. Entwickler von Modellierungs-, Schema- und Serialisierungswerkzeugen müssen sicherstellen, dass bei UML-Properties mit <code>aggregation = none</code> die Auswertung von Metamodell-Tags und Stereotypen bezüglich des Wrapper-Elements exakt dieser Fallunterscheidung folgt, um standardkonforme ARXML-Strukturen zu gewährleisten.</p>"}], "trans": [{"from": "FIG-2bcf62b28e396ca6", "to": "FIG-05b7b8d6f986c53b", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
